uniform float iTime;
uniform vec2 iResolution;
uniform vec4 iMouse;

// --- STANDARD CONTROLS ---
uniform float u_speed;
uniform float u_camera_dist; 
uniform float u_fov;
uniform float u_glow_intensity;

// --- VISUAL CONTROLS ---
uniform float u_turbulence_strength;
uniform float u_cloud_height; // Ribbon Thickness
uniform float u_color_shift;
uniform float u_density_factor;
uniform float u_saturation;

out vec4 fragColor;

// --- LUMINA MATH LIB ---
mat2 rot(float a) {
    float s = sin(a), c = cos(a);
    return mat2(c, -s, s, c);
}

// Lush Silk Palette: Teal, Purple, Pink, and Soft White
vec3 hsv2rgb(vec3 c) {
    vec4 K = vec4(1.0, 2.0 / 3.0, 1.0 / 3.0, 3.0);
    vec3 p = abs(fract(c.xxx + K.xyz) * 6.0 - K.www);
    return c.z * mix(K.xxx, clamp(p - K.xxx, 0.0, 1.0), c.y);
}

void main() {
    vec2 uv = (gl_FragCoord.xy - 0.5 * iResolution.xy) / iResolution.y;
    vec3 rd = normalize(vec3(uv, -1.0 / max(0.1, u_fov))); 

    float t = iTime * ((u_speed <= 0.0) ? 0.15 : u_speed * 0.3);

    // Accumulation
    vec4 col = vec4(0.0);

    // Start distance for broad perspective
    float d = 0.5 + u_camera_dist; 

    for(int i = 0; i < 70; i++) {
        vec3 p = d * rd;

        // --- SILK FLOW TURBULENCE ---
        // Slower, wider frequencies to create "Sheets" instead of "Strings"
        float scale = 0.8; 
        vec3 p_orig = p;
        for(int j = 0; j < 4; j++) {
            p.xy *= rot(t * 0.02 + float(j) * 0.4);
            // Swizzling for graceful, broad waves
            p += u_turbulence_strength * sin(p.yzx * scale + t * 0.5) / scale;
            scale *= 1.4;
        }

        // --- TRANSLUCENT SHEET LOGIC ---
        // Using a Sine-based grid with a power function for "Silky" gradients
        float sheets = sin(p.y * 3.0 + p.z * 1.5 + t * 0.2);
        float ribbons = u_cloud_height - abs(sheets); 

        // Step size adjusted for translucency
        float stepSize = 0.03 + max(ribbons, -ribbons * 0.2) * 0.5;
        d += stepSize;

        // --- ELEGANT COLORING ---
        // Maps the hue across the sweeping waves
        float hue = fract(u_color_shift + p_orig.x * 0.03 + p_orig.z * 0.05);
        vec3 silkColor = hsv2rgb(vec3(hue, clamp(u_saturation, 0.3, 0.8), 1.0));

        // Exponential glow for that "backlit" Getty look
        float glow = exp(ribbons / (0.4 / max(0.01, u_density_factor)));

        // Additive alpha blending for soft overlaps
        vec4 layer = vec4(silkColor * glow * (u_glow_intensity * 0.01), glow * 0.05);
        col += layer * (1.0 - col.a); 

        if (col.a > 0.99) break;
    }

    // --- FINAL POST-PROC ---
    vec3 finalCol = col.rgb;

    // Soft tone mapping for silky highlights
    finalCol = 1.0 - exp(-finalCol * 1.5);

    // Pastel push - boosting the mids
    finalCol = pow(finalCol, vec3(0.9, 1.0, 1.1));

    // Soft vignette
    finalCol *= smoothstep(1.8, 0.5, length(uv));

    fragColor = vec4(clamp(finalCol, 0.0, 1.0), 1.0);
}
